def icon(name, cls="", style=""):
    """Inline lucide SVG (24x24 stroke) by name; empty string for an unknown name."""
    body = ICONS.get(name, "")
    attrs = ""
    if cls:
        attrs += f' class="{cls}"'
    if style:
        attrs += f' style="{style}"'
    return (f'<svg{attrs} viewBox="0 0 24 24" fill="none" stroke="currentColor" '
            f'stroke-width="2" stroke-linecap="round" stroke-linejoin="round">{body}</svg>')
